function applyPatches(root, patches){
  // patches: [{id, type, selector, value, ts}]
  patches.sort((a,b)=> a.id - b.id);
  for(const p of patches){
    // minimal DOM update logic depending on type
    const el = root.querySelector(p.selector);
    if(!el) continue;
    switch(p.type){
      case 'update': el.textContent = p.value; break;
